import java.util.Locale;

public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 9; i++) {
            for (int j = 1; j <= 9; j++) {
                System.out.printf(Locale.ROOT, "%3d", i * j);
            }
            System.out.println();
        }
    }
}
